import numpy as np
from scipy.integrate import solve_ivp
from solver import Solver
import time

def solve_reference(problem):
    t0 = problem["t0"]
    t1 = problem["t1"]
    y0 = problem["y0"]
    params = problem["params"]
    beta = params["beta"]
    sigma = params["sigma"]
    gamma = params["gamma"]
    omega = params["omega"]
    sol = solve_ivp(
        fun=lambda t, y: [-beta*y[0]*y[2] + omega*y[3],
                          beta*y[0]*y[2] - sigma*y[1],
                          sigma*y[1] - gamma*y[2],
                          gamma*y[2] - omega*y[3]],
        t_span=(t0, t1),
        y0=y0,
        method='DOP853',
        rtol=1e-12,
        atol=1e-14,
    )
    return sol.y[:, -1]

def verify_solution(problem, result, ref):
    atol, rtol = 1e-8, 1e-5
    rel_diff = np.max(np.abs((np.array(result) - ref) / (atol + rtol * np.abs(ref))))
    return rel_diff < 1.0, rel_diff

solver = Solver()

# Test cases
test_cases = [
    {
        'name': 'Standard case',
        'problem': {
            't0': 0.0, 't1': 400.0,
            'y0': [0.89, 0.01, 0.005, 0.095],
            'params': {'beta': 0.35, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.002}
        }
    },
    {
        'name': 'Short time',
        'problem': {
            't0': 0.0, 't1': 10.0,
            'y0': [0.99, 0.01, 0.0, 0.0],
            'params': {'beta': 0.8, 'sigma': 0.3, 'gamma': 0.2, 'omega': 0.001}
        }
    },
    {
        'name': 'Long time',
        'problem': {
            't0': 0.0, 't1': 1000.0,
            'y0': [0.5, 0.3, 0.2, 0.0],
            'params': {'beta': 1.5, 'sigma': 0.5, 'gamma': 0.3, 'omega': 0.1}
        }
    },
    {
        'name': 'High transmission',
        'problem': {
            't0': 0.0, 't1': 200.0,
            'y0': [0.95, 0.05, 0.0, 0.0],
            'params': {'beta': 2.0, 'sigma': 0.5, 'gamma': 0.1, 'omega': 0.01}
        }
    },
    {
        'name': 'Low immunity loss',
        'problem': {
            't0': 0.0, 't1': 500.0,
            'y0': [0.8, 0.1, 0.05, 0.05],
            'params': {'beta': 0.4, 'sigma': 0.25, 'gamma': 0.15, 'omega': 0.0001}
        }
    },
    {
        'name': 'Fast dynamics',
        'problem': {
            't0': 0.0, 't1': 50.0,
            'y0': [0.7, 0.2, 0.1, 0.0],
            'params': {'beta': 3.0, 'sigma': 1.0, 'gamma': 0.5, 'omega': 0.2}
        }
    },
]

all_pass = True
for tc in test_cases:
    ref = solve_reference(tc['problem'])
    result = solver.solve(tc['problem'])
    passed, rel_diff = verify_solution(tc['problem'], result, ref)
    sum_val = sum(result)

    print(f"{tc['name']}: {'PASS' if passed else 'FAIL'} (rel_diff={rel_diff:.4f}, sum={sum_val:.10f})")
    if not passed:
        all_pass = False
        print(f"  Result: {result}")
        print(f"  Reference: {ref}")

print(f"\nAll tests passed: {all_pass}")

# Benchmark
start = time.time()
for _ in range(1000):
    solver.solve(test_cases[0]['problem'])
elapsed = (time.time() - start) / 1000
print(f"\nAverage solve time: {elapsed*1000:.3f} ms")
