import sys
sys.path.insert(0, '/app')
import numpy as np
from scipy.integrate import solve_ivp
import logging
from solver import Solver

# Exact verification function from the task
def is_solution(problem, solution):
    if not all(k in problem for k in ["params", "y0", "t0", "t1"]):
        logging.error("Problem dictionary missing required keys.")
        return False

    try:
        y0_arr = np.array(problem["y0"])
        proposed_array = np.array(solution, dtype=float)
    except Exception:
        logging.error("Could not convert 'y_final' or 'y0' to numpy arrays.")
        return False

    if proposed_array.shape != y0_arr.shape:
        logging.error(f"Output shape {proposed_array.shape} != input shape {y0_arr.shape}.")
        return False
    if not np.all(np.isfinite(proposed_array)):
        logging.error("Proposed 'y_final' contains non-finite values.")
        return False

    # Check if the solution components sum to approximately 1 (conservation law)
    if not np.isclose(np.sum(proposed_array), 1.0, rtol=1e-5, atol=1e-8):
        logging.error(f"Solution components sum to {np.sum(proposed_array)}, not 1.0 (conservation violation).")
        return False

    try:
        # Use the solver to get reference solution
        solver_ref = Solver()
        ref_solution = solver_ref.solve(problem)
        ref_array = np.array(ref_solution)
    except Exception as e:
        logging.error(f"Error computing reference solution: {e}")
        return False

    if ref_array.shape != y0_arr.shape:
        logging.error(f"Reference shape {ref_array.shape} mismatch input {y0_arr.shape}.")
        return False
    if not np.all(np.isfinite(ref_array)):
        logging.error("Reference solution contains non-finite values.")
        return False

    rtol, atol = 1e-5, 1e-8
    if not np.allclose(proposed_array, ref_array, rtol=rtol, atol=atol):
        abs_diff = np.max(np.abs(proposed_array - ref_array))
        rel_diff = np.max(
            np.abs((proposed_array - ref_array) / (atol + rtol * np.abs(ref_array)))
        )
        logging.error(f"Solution verification failed: max abs err={abs_diff:.3g}, max rel err={rel_diff:.3g}")
        return False

    return True

# Create solver
solver = Solver()

# Test cases
test_problems = [
    {
        'name': 'Example from task',
        'problem': {
            't0': 0.0, 't1': 400.0,
            'y0': [0.89, 0.01, 0.005, 0.095],
            'params': {'beta': 0.35, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.002}
        }
    },
    {
        'name': 'High transmission',
        'problem': {
            't0': 0.0, 't1': 200.0,
            'y0': [0.95, 0.05, 0.0, 0.0],
            'params': {'beta': 2.0, 'sigma': 0.5, 'gamma': 0.1, 'omega': 0.01}
        }
    },
    {
        'name': 'Long time horizon',
        'problem': {
            't0': 0.0, 't1': 1000.0,
            'y0': [0.5, 0.3, 0.2, 0.0],
            'params': {'beta': 1.5, 'sigma': 0.5, 'gamma': 0.3, 'omega': 0.1}
        }
    },
]

print("Running final verification tests...")
print("=" * 60)
all_pass = True
for tc in test_problems:
    result = solver.solve(tc['problem'])
    passed = is_solution(tc['problem'], result)
    print(f"{tc['name']}: {'PASS' if passed else 'FAIL'}")
    if not passed:
        all_pass = False

print("=" * 60)
print(f"\nAll tests passed: {all_pass}")

if all_pass:
    print("\nSolver is ready for evaluation!")
