import numpy as np
from solver import Solver

solver = Solver()

print("Additional edge case tests...")
print("-" * 60)

def test(name, problem, should_pass=True):
    try:
        result = solver.solve(problem)
        sum_val = sum(result)
        ok = abs(sum_val - 1.0) < 1e-6 and all(0 <= x <= 1 for x in result)
        status = 'PASS' if ok == should_pass else 'FAIL'
        print(f"{name:30s}: {status} (sum={sum_val:.10f})")
        return ok
    except Exception as e:
        print(f"{name:30s}: ERROR - {e}")
        return False

# Test with t0 > 0
test('t0 > 0', {
    't0': 100.0, 't1': 500.0,
    'y0': [0.89, 0.01, 0.005, 0.095],
    'params': {'beta': 0.35, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.002}
})

# Test with y0 that doesn't sum to 1 (should still work)
test('y0 not summing to 1', {
    't0': 0.0, 't1': 100.0,
    'y0': [0.5, 0.2, 0.1, 0.1],  # sums to 0.9
    'params': {'beta': 0.5, 'sigma': 0.3, 'gamma': 0.2, 'omega': 0.01}
})

# Test with very small initial values
test('Very small y0 values', {
    't0': 0.0, 't1': 50.0,
    'y0': [0.999, 0.001, 0.0, 0.0],
    'params': {'beta': 0.5, 'sigma': 0.3, 'gamma': 0.2, 'omega': 0.01}
})

# Test with extreme beta/sigma ratio
test('Extreme beta/sigma ratio', {
    't0': 0.0, 't1': 200.0,
    'y0': [0.99, 0.01, 0.0, 0.0],
    'params': {'beta': 10.0, 'sigma': 0.01, 'gamma': 0.1, 'omega': 0.001}
})

# Test with t1 < t0 (should this work? probably not, but let's see)
try:
    result = solver.solve({
        't0': 100.0, 't1': 50.0,
        'y0': [0.89, 0.01, 0.005, 0.095],
        'params': {'beta': 0.35, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.002}
    })
    print(f"{'t1 < t0':30s}: Result = {result} (unexpected)")
except Exception as e:
    print(f"{'t1 < t0':30s}: Handled gracefully - {e}")

print("-" * 60)
print("\nAll additional tests completed.")
